class Solution:
    def decodeMessage(self, key: str, message: str) -> str:
        f = lambda x: ord(x)-ord('a')
        lookup = [-1]*26
        i = 0
        for x in map(f, key):
            if x < 0 or lookup[x] != -1:
                continue
            lookup[x] = i
            i += 1
        return "".join(map(lambda x: chr(ord('a')+x), (lookup[x] if x >= 0 else x for x in map(f, message))))
